package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsAny_TriageGen0Test {

    @Test
    public void testContainsAny_NullCharSequence() {
        assertFalse(StringUtils.containsAny(null, new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        assertFalse(StringUtils.containsAny("", new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse(StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse(StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse(StringUtils.containsAny("xyz", new char[]{'a', 'b', 'c'}));
    }

    @Test
    public void testContainsAny_SingleMatchAtStart() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_SingleMatchInMiddle() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'b'}));
    }

    @Test
    public void testContainsAny_SingleMatchAtEnd() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_MultipleMatches() {
        assertTrue(StringUtils.containsAny("abcdef", new char[]{'b', 'e'}));
    }

    @Test
    public void testContainsAny_SearchCharsLargerThanCs() {
        assertTrue(StringUtils.containsAny("a", new char[]{'z', 'y', 'a', 'x'}));
    }

    @Test
    public void testContainsAny_UnicodeBasicMultilingualPlane() {
        // Testing characters in the BMP as per code comments
        assertTrue(StringUtils.containsAny("Hello \u1234 World", new char[]{'\u1234'}));
    }

    @Test
    public void testContainsAny_SingleCharacterString() {
        assertTrue(StringUtils.containsAny("a", new char[]{'a'}));
        assertFalse(StringUtils.containsAny("a", new char[]{'b'}));
    }
}
